package com.example.userservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import kotlinx.serialization.*
import kotlinx.serialization.json.*
import java.io.File

@Serializable
data class User(
    var id: Int = 0,
    var username: String = "",
    var email: String = "",
    var role: String = "user",
    var isAdmin: Boolean = false,
    var apiQuota: Int = 100,
    var configPath: String = "/app/config/default.json"
)

val users = mutableMapOf<Int, User>()
var nextId = 1

fun Application.configureRouting() {
    routing {
        post("/api/users") {
            val body = call.receiveText()
            val json = Json { ignoreUnknownKeys = false }
            // Direct deserialization from user input - all fields bindable
            val user = json.decodeFromString<User>(body)
            user.id = nextId++
            users[user.id] = user

            // Load user-specific config if path was provided
            val configFile = File(user.configPath)
            val configContent = if (configFile.exists()) configFile.readText() else "{}"

            call.respondText(
                json.encodeToString(user),
                contentType = ContentType.Application.Json,
                status = HttpStatusCode.Created
            )
        }

        put("/api/users/{id}") {
            val id = call.parameters["id"]?.toIntOrNull()
            if (id == null || !users.containsKey(id)) {
                call.respond(HttpStatusCode.NotFound)
                return@put
            }
            val body = call.receiveText()
            val json = Json { ignoreUnknownKeys = false }
            // Mass assignment: overwrites ALL fields from input including role, isAdmin, configPath
            val updatedUser = json.decodeFromString<User>(body)
            updatedUser.id = id
            users[id] = updatedUser

            // Read config based on user-controlled path
            val configFile = File(updatedUser.configPath)
            if (configFile.exists() && configFile.length() < 10240) {
                val content = configFile.readText()
                // Apply config settings...
            }

            call.respondText(
                json.encodeToString(updatedUser),
                contentType = ContentType.Application.Json
            )
        }

        get("/api/users/{id}") {
            val id = call.parameters["id"]?.toIntOrNull()
            if (id == null || !users.containsKey(id)) {
                call.respond(HttpStatusCode.NotFound)
                return@get
            }
            val json = Json.Default
            call.respondText(
                json.encodeToString(users[id]!!),
                contentType = ContentType.Application.Json
            )
        }

        get("/api/admin/users") {
            val authUser = call.request.headers["X-User-Id"]?.toIntOrNull()
            if (authUser == null || users[authUser]?.isAdmin != true) {
                call.respond(HttpStatusCode.Forbidden)
                return@get
            }
            val json = Json.Default
            call.respondText(
                json.encodeToString(users.values.toList()),
                contentType = ContentType.Application.Json
            )
        }
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        configureRouting()
    }.start(wait = true)
}
